import 'package:flutter/material.dart';
import 'package:lazerus_core/lazerus_core.dart';

import 'color/color_macro_editor_node_module.dart';
import 'color_brightness_combine/color_brightness_combine_macro_editor_node_module.dart';
import 'lighting_target/lighting_target_macro_editor_node_module.dart';
import 'macro_editor_node_module.dart';
import 'microphone/microphone_macro_editor_node_module.dart';
import 'multiband_eq/multiband_eq_macro_editor_node_module.dart';
import 'strobe/strobe_macro_editor_node_module.dart';

/// Presentation composition root for installed macro node families.
///
/// This is deliberately the only presentation file that imports several
/// concrete node modules. [MacroEditorPage] sees only this registry and the
/// [MacroEditorNodeModule] contract.
final class MacroEditorNodeModuleRegistry {
  MacroEditorNodeModuleRegistry(Iterable<MacroEditorNodeModule> modules)
    : _modules = List<MacroEditorNodeModule>.unmodifiable(modules) {
    final kinds = _modules.map((module) => module.kind).toSet();
    if (kinds.length != _modules.length) {
      throw ArgumentError.value(
        modules,
        'modules',
        'Each editor node module kind must be unique.',
      );
    }
  }

  final List<MacroEditorNodeModule> _modules;
  final MacroEditorNodeModule _unsupported =
      _UnsupportedMacroEditorNodeModule();

  MacroEditorNodeModule moduleFor(MacroNode node) {
    for (final module in _modules) {
      if (module.supports(node)) return module;
    }
    return _unsupported;
  }

  String titleFor(MacroNode node) => moduleFor(node).titleFor(node);

  Iterable<MacroEditorPaletteEntry> paletteEntries(
    MacroEditorNodePresentationState state,
  ) sync* {
    for (final module in _modules) {
      yield* module.paletteEntries(state);
    }
  }

  MacroNode? createNode(
    MacroEditorPaletteEntry entry, {
    required MacroEditorNewId newId,
  }) {
    for (final module in _modules) {
      if (module.kind == entry.moduleKind) {
        return module.createNode(entry, newId: newId);
      }
    }
    return null;
  }

  /// Rebuilds only the portable target bindings contributed by registered
  /// binding modules. The editor itself never examines a concrete sink kind.
  MacroGraph synchronizeBindings(MacroGraph graph) {
    final bindings = <MacroTargetBinding>[];
    for (final module in _modules) {
      if (module is! MacroEditorBindingModule) continue;
      final bindingModule = module as MacroEditorBindingModule;
      bindings.addAll(bindingModule.deriveTargetBindings(graph));
    }
    return graph.copyWith(targetBindings: bindings);
  }

  MacroGraph migrateLegacyBindings(
    MacroGraph graph, {
    required MacroEditorNewId newId,
  }) {
    var migrated = graph;
    for (final module in _modules) {
      if (module is! MacroEditorBindingModule) continue;
      final bindingModule = module as MacroEditorBindingModule;
      migrated = bindingModule.migrateLegacyBindings(migrated, newId: newId);
    }
    return synchronizeBindings(migrated);
  }

  /// Builds the default source → processor graph strictly from the starter
  /// module roles and their public port declarations.
  MacroGraph createStarterGraph({required MacroEditorNewId newId}) {
    final source = _starterFor(MacroEditorStarterRole.source);
    final processor = _starterFor(MacroEditorStarterRole.processor);
    if (source == null || processor == null) {
      return MacroGraph(
        id: newId(),
        name: 'New macro',
        nodes: const <MacroNode>[],
        edges: const <MacroEdge>[],
      );
    }
    final sourceNode = source.createStarterNode(newId: newId);
    final processorNode = processor.createStarterNode(newId: newId);
    final sourcePort = sourceNode.ports.where(
      (port) => port.direction == MacroPortDirection.output,
    );
    final processorPort = processorNode.ports.where(
      (port) => port.direction == MacroPortDirection.input,
    );
    final canConnect =
        sourcePort.isNotEmpty &&
        processorPort.isNotEmpty &&
        sourcePort.first.type == processorPort.first.type;
    return MacroGraph(
      id: newId(),
      name: 'Microphone lights',
      nodes: <MacroNode>[sourceNode, processorNode],
      edges: canConnect
          ? <MacroEdge>[
              MacroEdge(
                id: newId(),
                fromPortId: sourcePort.first.id,
                toPortId: processorPort.first.id,
              ),
            ]
          : const <MacroEdge>[],
      editorPositions: <String, MacroEditorPosition>{
        sourceNode.id: MacroEditorPosition(x: 48, y: 110),
        processorNode.id: MacroEditorPosition(x: 340, y: 110),
      },
    );
  }

  MacroEditorStarterNodeModule? _starterFor(MacroEditorStarterRole role) {
    for (final module in _modules) {
      if (module is! MacroEditorStarterNodeModule) continue;
      final starter = module as MacroEditorStarterNodeModule;
      if (starter.starterRole == role) return starter;
    }
    return null;
  }
}

MacroEditorNodeModuleRegistry createMacroEditorNodeModuleRegistry() =>
    MacroEditorNodeModuleRegistry(<MacroEditorNodeModule>[
      MicrophoneMacroEditorNodeModule(),
      MultibandEqMacroEditorNodeModule(),
      ColorMacroEditorNodeModule(),
      ColorBrightnessCombineMacroEditorNodeModule(),
      StrobeMacroEditorNodeModule(),
      LightingTargetMacroEditorNodeModule(),
    ]);

final class _UnsupportedMacroEditorNodeModule extends MacroEditorNodeModule {
  @override
  String get kind => 'unsupported';

  @override
  String titleFor(MacroNode node) => node.displayName ?? node.kind;

  @override
  Widget buildInspector(
    BuildContext context,
    MacroEditorNodeViewContext nodeContext,
  ) => MacroEditorNodeInspectorCard(
    title: titleFor(nodeContext.node),
    enabled: nodeContext.state.enabled,
    onRemove: nodeContext.removeNode,
    child: const Text(
      'Для цього збереженого node немає встановленого editor module. '
      'Він залишається repairable і не змінюється автоматично.',
    ),
  );
}
